"Урок 1. Музыкальная карта Казахстана": "Дарс 1. Харитаи мусиқии Қазоқистон",
"Музыкальная карта Казахстана": "Харитаи мусиқии Қазоқистон",
"Объяснять, чем похожи географическая и музыкальная карты, и узнавать современный (эстрадный) вокал.": "Фаҳмонда тавонистан, ки харитаи ҷуғрофӣ ва харитаи мусиқӣ чӣ монандӣ доранд, ва овозхонии муосирро (эстрадиро) шинохтан.",
"Две карты": "Ду харита",
"На географической карте отмечают города и области. На музыкальной карте отмечают места, связанные с музыкой и музыкантами.": "Дар харитаи ҷуғрофӣ шаҳрҳо ва вилоятҳоро қайд мекунанд. Дар харитаи мусиқӣ ҷойҳоеро қайд мекунанд, ки бо мусиқӣ ва мусиқинавозон алоқаманданд.",
"Великие музыканты на карте": "Мусиқинавозони бузург дар харита",
"На карте Казахстана значками показано место рождения великих музыкантов Коркыта и Даулеткерея. Так музыка «привязана» к земле.": "Дар харитаи Қазоқистон бо нишонаҳо ҷойи таваллуди мусиқинавозони бузург Коркыт ва Даулеткерей нишон дода шудааст. Ҳамин тавр мусиқӣ ба замин «пайваст» мешавад.",
"Музыкальные впечатления": "Таассуроти мусиқӣ",
"Музыкальные впечатления — это то, что ты услышал и запомнил. Можно рассказать, где ты слушал музыку, какое произведение услышал и чем оно запомнилось.": "Таассуроти мусиқӣ ин он аст, ки ту шунидӣ ва дар хотир нигоҳ доштӣ. Метавон нақл кард, ки мусиқиро дар куҷо шунидӣ, кадом асарро шунидӣ ва он бо чӣ дар хотир монд.",
"Современный (эстрадный) вокал": "Овозхонии муосир (эстрадӣ)",
"Современный, или эстрадный, вокал — это особый вид пения. Яркий пример — песня «Земля моя» в исполнении Розы Рымбаевой.": "Овозхонии муосир, ё эстрадӣ, навъи махсуси суруд хондан аст. Мисоли равшан суруди «Замини ман» бо иҷрои Роза Рымбаева мебошад.",
"Песни о Родине": "Сурудҳо дар бораи Ватан",
