"Урок 2. Музыкальный путеводитель": "Дарс 2. Роҳнамои мусиқӣ",
"Музыкальный путеводитель": "Роҳнамои мусиқӣ",
"Объяснять, что такое музыкальный путеводитель и аккомпанемент, называть композиторов урока и характеризовать классический вокал.": "Фаҳмонда тавонистан, ки роҳнамои мусиқӣ ва аккомпанемент чист, оҳангсозони дарсро номбар кардан ва овозхонии классикиро тавсиф додан.",
"Аккомпанемент": "Аккомпанемент",
"Аккомпанемент сопровождает мелодию. Так и музыка сопровождает нас во всех путешествиях. По-казахски это сүйемелдеу, по-английски accompaniment.": "Аккомпанемент оҳангро ҳамроҳӣ мекунад. Ҳамин тавр мусиқӣ моро дар ҳамаи сафарҳо ҳамроҳӣ мекунад. Ба қазоқӣ ин суйемелдеу, ба забони англисӣ accompaniment аст.",
"Путеводитель": "Роҳнамо",
"Это справочник для путешественников. Вся информация в нём собрана по принципу: кто? что? где?": "Ин маълумотнома барои сайёҳон аст. Тамоми маълумот дар он аз рӯи тартиби «кӣ? чӣ? дар куҷо?» ҷамъ карда шудааст.",
"Чтобы его составить, нужно подобрать интересные примеры музыкальной культуры Казахстана и указать, где можно узнать о них подробнее.": "Барои тартиб додани он бояд мисолҳои шавқовари фарҳанги мусиқии Қазоқистонро интихоб кард ва нишон дод, ки дар бораи онҳо дар куҷо муфассалтар донистан мумкин аст.",
"Композиторы урока": "Оҳангсозони дарс",
"Владимир Шаинский (1925–2017) — детский композитор. Ахмет Жубанов (1906–1968) — казахский композитор, основатель оркестра казахских народных инструментов (ОКНИ). Франц Йозеф Гайдн (1732–1809) — австрийский композитор.": "Владимир Шаинский (1925–2017) — оҳангсози кӯдакон. Ахмет Жубанов (1906–1968) — оҳангсози қазоқ, бунёдгузори оркестри асбобҳои мусиқии халқии қазоқ (ОҚНА). Франц Йозеф Гайдн (1732–1809) — оҳангсози австриягӣ.",
"Глинка и классический вокал": "Глинка ва овозхонии классикӣ",
"Михаил Иванович Глинка (1804–1857) — русский композитор, автор оперы «Руслан и Людмила», симфонической фантазии «Камаринская» и «Вальса-фантазии». «Попутная песня» Глинки — яркий пример классического вокала: голоса певцов этой школы отличаются силой. Классический вокал — традиционный способ пения, который встречается в опере, оперетте и академическом хоре.": "Михаил Иванович Глинка (1804–1857) — оҳангсози рус, муаллифи операи «Руслан ва Людмила», фантазияи симфонии «Камаринская» ва «Вальс-фантазия». «Суруди роҳ»-и Глинка мисоли равшани овозхонии классикӣ аст: овози сароёндагони ин мактаб бо қувват фарқ мекунад. Овозхонии классикӣ усули суннатии суруд хондан аст, ки дар опера, оперетта ва хори академӣ вомехӯрад.",
