"Урок 3. Красота родной земли — источник вдохновения": "Дарс 3. Зебоии замини зодгоҳ — сарчашмаи илҳом",
"Красота родной земли — источник вдохновения": "Зебоии замини зодгоҳ — сарчашмаи илҳом",
"Объяснять, как природа родного края вдохновляет композиторов, и различать вокал и вокализ.": "Фаҳмонда тавонистан, ки табиати зодгоҳ чӣ тавр оҳангсозонро илҳом мебахшад, ва вокал ва вокализро фарқ кардан.",
"Природа и музыка": "Табиат ва мусиқӣ",
"Природа Казахстана очень разная. Красота родного края вдохновляла композиторов создавать свои произведения.": "Табиати Қазоқистон хеле гуногун аст. Зебоии зодгоҳ оҳангсозонро ба эҷоди асарҳояшон илҳом мебахшид.",
"Родной пейзаж": "Манзараи зодгоҳ",
"Где бы ни жил человек — у величественного Илейского Алатау или в бескрайней степи Сарыарки, — пейзаж родного края для него самый красивый.": "Одам дар куҷо зиндагӣ накунад — назди Илейский Алатауи боазамат ё дар даштҳои бепоёни Сарыарқа, — манзараи зодгоҳ барояш зеботарин аст.",
"Кюй «Алатау»": "Кюи «Алатау»",
"Кюй «Алатау» написал композитор Курмангазы Сагырбайулы. Слушая его, можно подобрать слова, которые описывают характер музыки.": "Кюи «Алатау»-ро оҳангсоз Курмангазы Сағырбайулы навиштааст. Ҳангоми гӯш кардани он калимаҳоеро интихоб кардан мумкин аст, ки хусусияти мусиқиро тасвир мекунанд.",
"Вокал и вокализ": "Вокал ва вокализ",
"Вокал — это пение. Вокализ — когда мелодию исполняют голосом без слов, без текста.": "Вокал — ин суруд хондан аст. Вокализ — ҳангоме, ки оҳангро бо овоз бе калимаҳо, бе матн иҷро мекунанд.",
"Джузеппе Верди": "Ҷузеппе Верди",
"Джузеппе Верди (1813–1901) — итальянский композитор. Его творчество — одно из крупнейших достижений мирового оперного искусства. Он написал оперу «Набукко» («Навуходоносор»).": "Ҷузеппе Верди (1813–1901) — оҳангсози итолиёвӣ. Эҷодиёти ӯ яке аз бузургтарин дастовардҳои санъати операи ҷаҳонӣ аст. Ӯ операи «Набукко» («Навуходоносор»)-ро навиштааст.",
"Разложи: вокал или вокализ": "Ҷудо кун: вокал ё вокализ",
"Прочитай карточку и реши, о чём она: о вокале или о вокализе.": "Корточаро хон ва қарор деҳ, ки дар бораи чӣ аст: дар бораи вокал ё вокализ.",
