"Урок 4. С чего начинается Родина?": "Дарс 4. Ватан аз куҷо сар мешавад?",
"С чего начинается Родина?": "Ватан аз куҷо сар мешавад?",
"Объяснять, что такое народный вокал, и называть длительности нот и пауз.": "Фаҳмонда тавонистан, ки овозхонии халқӣ чист, ва давомнокии нотаҳо ва таваққуфҳоро номбар кардан.",
"Родина начинается с дома": "Ватан аз хона сар мешавад",
"Казахская поговорка говорит, что дорога начинается с порога родного дома. Родина — это дом, близкие, праздники и песни, которые мы берегём в сердце.": "Зарбулмасали қазоқӣ мегӯяд, ки роҳ аз остонаи хонаи падарӣ сар мешавад. Ватан — ин хона, наздикон, ҷашнҳо ва сурудҳоест, ки мо дар дил эҳтиёт мекунем.",
"Колыбельная": "Алла",
"Самая первая песня, которую мы слышим, — песня мамы. Во всех странах колыбельная — символ материнской любви, заботы и ласки.": "Аввалин суруде, ки мешунавем, суруди модар аст. Дар ҳамаи кишварҳо алла рамзи муҳаббат, ғамхорӣ ва навозиши модарона аст.",
"Ласточка — символ дома": "Парастук — рамзи хона",
"Многие народы считают ласточку символом родного дома. Поэтому песни о ласточке напоминают нам о Родине.": "Бисёр халқҳо парастукро рамзи хонаи падарӣ медонанд. Барои ҳамин сурудҳо дар бораи парастук моро ба ёди Ватан меоранд.",
"Народный вокал": "Овозхонии халқӣ",
"Это вид пения, в основе которого лежат вокальные традиции конкретного народа. Часто народные исполнители поют в особой «разговорной» манере, горловым «плоским» звуком.": "Ин навъи суруд хондан аст, ки дар асоси анъанаҳои овозхонии халқи муайян қарор дорад. Иҷрокунандагони халқӣ аксар вақт бо тарзи махсуси «гуфтугӯӣ», бо садои гулӯӣ ва «ҳамвор» месароянд.",
"Ноты, паузы и длительности": "Нотаҳо, таваққуфҳо ва давомнокӣ",
"Есть целая, половинная, четвертная и восьмая ноты. Пауза — это тишина в музыке, и равные по длительности ноты и паузы называются одинаково.": "Нотаи бутун, ним, чорякӣ ва ҳаштӣ ҳаст. Таваққуф — ин хомӯшӣ дар мусиқӣ аст, ва нотаҳо ва таваққуфҳои аз рӯи давомнокӣ баробар як хел номида мешаванд.",
"Разложи по длительности": "Аз рӯи давомнокӣ ҷудо кун",
"Определи, к какой длительности относится каждая карточка.": "Муайян кун, ки ҳар як корточка ба кадом давомнокӣ тааллуқ дорад.",
"К какой длительности относится?": "Ба кадом давомнокӣ тааллуқ дорад?",
