"Неверно. Колыбельная есть у любого народа.": "Нодуруст. Алла дар назди ҳар халқ ҳаст.",
"Верно. Ласточка — символ дома.": "Дуруст. Парастук — рамзи хона.",
"Неверно. Он основан на вокальных традициях конкретного народа.": "Нодуруст. Он ба анъанаҳои овозхонии халқи муайян асос ёфтааст.",
