"Урок 5. Ты — Человек!": "Дарс 5. Ту — Инсон!",
"Ты — Человек!": "Ту — Инсон!",
"Называть вечные человеческие ценности и рассказывать о сиртаки, композиторе Микисе Теодоракисе и песне «Ты — Человек».": "Арзишҳои абадии инсониро номбар кардан ва дар бораи сиртакӣ, оҳангсоз Микис Теодоракис ва суруди «Ту — Инсон» нақл кардан.",
"Человеческие ценности": "Арзишҳои инсонӣ",
"Любовь, добро, мир, Родина, семья, природа, красота и дружба — вечные человеческие ценности. Ими дорожит каждый человек.": "Муҳаббат, некӣ, сулҳ, Ватан, оила, табиат, зебоӣ ва дӯстӣ арзишҳои абадии инсонианд. Ҳар як инсон онҳоро қадр мекунад.",
"О чём говорит музыка": "Мусиқӣ дар бораи чӣ нақл мекунад",
"Многие музыкальные произведения рассказывают об этих ценностях. Музыка передаёт мысли и переживания человека и рисует картины природы.": "Бисёр асарҳои мусиқӣ дар бораи ин арзишҳо нақл мекунанд. Мусиқӣ фикру эҳсосоти инсонро мерасонад ва манзараҳои табиатро тасвир мекунад.",
"Микис Теодоракис": "Микис Теодоракис",
"Это греческий композитор и дирижёр. Он написал много симфоний, камерных произведений, а также популярных песен и танцев в народном стиле.": "Ин оҳангсоз ва дирижёри юнонӣ аст. У бисёр симфонияҳо, асарҳои камерӣ ва инчунин сурудҳо ва рақсҳои машҳури мардумиро навиштааст.",
"Сиртаки": "Сиртакӣ",
"Это самый популярный греческий танец в мире и один из символов Греции. Его принято считать народным, но на самом деле музыку придумал Микис Теодоракис.": "Ин машҳуртарин рақси юнонӣ дар ҷаҳон ва яке аз рамзҳои Юнон аст. Онро одатан мардумӣ мешуморанд, вале дар асл мусиқиашро Микис Теодоракис эҷод кардааст.",
"Песня «Ты — Человек»": "Суруди «Ту — Инсон»",
