"Урок 6. Нам песня строить и жить помогает": "Дарс 6. Суруд ба мо дар сохтан ва зистан кумак мекунад",
"Нам песня строить и жить помогает": "Суруд ба мо дар сохтан ва зистан кумак мекунад",
"Объяснять, как песня помогает человеку в жизни, и называть композиторов Б. Байкадамова и И. Дунаевского": "Фаҳмонидан, ки суруд ба инсон дар зиндагӣ чӣ тавр кумак мекунад, ва номбар кардани оҳангсозон Б. Байкадамов ва И. Дунаевский",
"Песня и человек": "Суруд ва инсон",
"С песней мы радуемся и грустим. Песня — верный спутник человека в радости и в печали.": "Бо суруд мо шод мешавем ва андуҳгин мешавем. Суруд ҳамроҳи боэътимоди инсон дар шодӣ ва ғам аст.",
"Где звучат песни": "Сурудҳо дар куҷо садо медиҳанд",
"Весёлые, задорные, шуточные и лиричные песни звучат на детских праздниках, в походах, во время отдыха и работы.": "Сурудҳои шодмон, ҷӯшон, шӯхӣ ва лирикӣ дар ҷашнҳои кӯдакона, дар сафарҳо, ҳангоми истироҳат ва кор садо медиҳанд.",
"Чему учат песни": "Сурудҳо чиро меомӯзонанд",
"Авторы часто описывали в песнях достоинства и недостатки, поступки людей. Так песня помогает стать лучше и добрее.": "Муаллифон дар сурудҳо аксар вақт хубиҳо ва камбудиҳо, кирдорҳои одамонро тасвир мекарданд. Ба ин тариқ суруд ба инсон кумак мекунад, ки беҳтар ва меҳрубонтар шавад.",
"Бахытжан Байкадамов": "Бахытжан Байкадамов",
"Казахский композитор (1917–1977), основоположник хорового пения в Казахстане, первый аранжировщик кюев и народных песен.": "Оҳангсози қазоқ (1917–1977), асосгузори хонандагии хорӣ дар Қазоқистон, аввалин аранжировкачии кюйҳо ва сурудҳои мардумӣ.",
"Исаак Дунаевский": "Исаак Дунаевский",
