"Голоса по высоте": "Овозҳо аз рӯи баландӣ",
"Певческие голоса бывают высокие, средние и низкие. Слушатель может больше любить низкие, средние или высокие голоса.": "Овозҳои хонандагӣ баланд, миёна ва паст мешаванд. Шунаванда метавонад овозҳои пастро, миёнаро ё баландро бештар дӯст дорад.",
"Детские голоса": "Овозҳои кӯдакона",
"У детей бывают дискант (высокий голос) и альт (средний голос).": "Кӯдакон дискант (овози баланд) ва альт (овози миёна) доранд.",
"Женские и мужские голоса": "Овозҳои занона ва мардона",
"Женские голоса: сопрано, меццо-сопрано, контральто. Мужские: тенор, баритон, бас.": "Овозҳои занона: сопрано, меццо-сопрано, контральто. Мардона: тенор, баритон, бас.",
"Ансамбль": "Ансамбл",
"Слово «ансамбль» по-французски значит «вместе». Это когда несколько человек вместе играют, поют или танцуют. Двое исполнителей — дуэт.": "Калимаи «ансамбл» ба забони фаронсавӣ маънои «якҷоя»-ро дорад. Ин вақтест, ки якчанд нафар якҷоя менавозанд, мехонанд ё рақс мекунанд. Ду иҷрокунанда — дуэт.",
"Состав ансамбля": "Таркиби ансамбл",
"Трио — три музыканта, квартет — четыре, квинтет — пять, секстет — шесть, септет — семь, октет — восемь, нонет — девять. Большой коллектив — оркестр, ансамбль певцов — хор. Ими руководит дирижёр.": "Трио — се навозанда, квартет — чор, квинтет — панҷ, секстет — шаш, септет — ҳафт, октет — ҳашт, нонет — нӯҳ. Гурӯҳи калон — оркестр, ансамбли хонандагон — хор. Онҳоро дирижёр роҳбарӣ мекунад.",
"Разложи голоса": "Овозҳоро ҷудо кун",
"Определи, кому принадлежит каждый певческий голос.": "Муайян кун, ки ҳар як овози хонандагӣ аз они кист.",
"Чей это голос?": "Ин овози кист?",
