"Урок 8. Песни мудрости": "Дарс 8. Сурудҳои ҳикмат",
"Песни мудрости": "Сурудҳои ҳикмат",
"Объяснять, что такое рондо, и различать в нём рефрен и эпизоды.": "Фаҳмонидан, ки рондо чист, ва дар он рефрен ва эпизодҳоро фарқ кардан.",
"Рондо": "Рондо",
"Рондо — это музыкальная форма. В ней неизменная тема чередуется с разными эпизодами.": "Рондо — шакли мусиқӣ аст. Дар он мавзӯи тағйирнаёбанда бо эпизодҳои гуногун ивазона меояд.",
"Рефрен": "Рефрен",
"Рефрен — это основная мелодия. Она возвращается в рондо снова и снова.": "Рефрен — оҳанги асосӣ аст. Он дар рондо бори дигар ва боз бармегардад.",
"Эпизод": "Эпизод",
"Эпизод — это дополнительная мелодия. Эпизоды между возвращениями рефрена разные.": "Эпизод — оҳанги иловагӣ аст. Эпизодҳо дар байни бозгаштҳои рефрен гуногунанд.",
"Цепочка событий": "Занҷири ҳодисаҳо",
"Сказка А.С. Пушкина «О рыбаке и рыбке» тоже как цепочка: повторяется встреча старика с золотой рыбкой, а между встречами происходят разные события.": "Афсонаи А.С. Пушкин «Дар бораи моҳигир ва моҳичаи тиллоӣ» низ ба занҷир монанд аст: вохӯрии пирамард бо моҳичаи тиллоӣ такрор мешавад, ва дар байни вохӯриҳо ҳодисаҳои гуногун рӯй медиҳанд.",
"Рондо и наша жизнь": "Рондо ва зиндагии мо",
"Мы часто возвращаемся к одному и тому же: идём на учёбу или прогулку и с радостью возвращаемся домой. Рондо запоминает такую закономерность в музыке.": "Мо аксар вақт ба як чиз бармегардем: ба дарс ё сайр меравем ва бо шодӣ ба хона бармегардем. Рондо чунин қонуниятро дар мусиқӣ нигоҳ медорад.",
"Разложи: рефрен или эпизод": "Ҷудо кун: рефрен ё эпизод",
"Основная мелодия": "Оҳанги асосӣ",
"Это главная мелодия рондо.": "Ин оҳанги асосии рондо аст.",
"Неизменная тема, которая возвращается": "Мавзӯи тағйирнаёбанда, ки бармегардад",
"Она повторяется в рондо.": "Он дар рондо такрор мешавад.",
"Встреча старика с золотой рыбкой в сказке": "Вохӯрии пирамард бо моҳичаи тиллоӣ дар афсона",
"Это событие повторяется снова и снова.": "Ин ҳодиса бори дигар ва боз такрор мешавад.",
"Возвращение домой после учёбы или прогулки": "Бозгашт ба хона пас аз дарс ё сайр",
"К этому мы возвращаемся каждый раз.": "Мо ҳар дафъа ба ин бармегардем.",
"Дополнительная мелодия": "Оҳанги иловагӣ",
"Она не главная, а добавочная.": "Он асосӣ нест, балки иловагӣ аст.",
"Мелодия, которая каждый раз новая": "Оҳанге, ки ҳар дафъа нав аст",
"Эпизоды между рефренами разные.": "Эпизодҳо дар байни рефренҳо гуногунанд.",
"Пёстрые, переменчивые желания старухи": "Хоҳишҳои рангоранг ва тағйирёбандаи пиразан",
"Эти события в сказке всё время меняются.": "Ин ҳодисаҳо дар афсона пайваста тағйир меёбанд.",
"Разные события между повторами": "Ҳодисаҳои гуногун дар байни такрорҳо",
"Между возвращениями рефрена звучит что-то новое.": "Дар байни бозгаштҳои рефрен чизи нав садо медиҳад.",
