"Менің елім": "Ватани ман",
"Мемлекеттік рәміздерді атау, Гимннің не екенін және оның авторларын айту, «Дарқан дала» әнінің авторларын ажырату.": "Рамзҳои давлатиро номбар кардан, фаҳмонидани он ки Суруди миллӣ чист ва муаллифонаш кистанд, муаллифони сурудаи «Даркан дала»-ро фарқ кардан.",
"Біздің Отанымыз": "Ватани мо",
"Біздің туған жеріміз, Отанымыз — Қазақстан. Біз жеріміздің сұлулығымен және халықтардың бірлігімен мақтанамыз.": "Диёри зодгоҳии мо, Ватани мо — Қазоқистон. Мо аз зебоии замини худ ва ягонагии халқҳо ифтихор мекунем.",
"Мемлекеттік рәміздер": "Рамзҳои давлатӣ",
"Еліміздің мемлекеттік рәміздері — Ту, Елтанба және Қазақстан Республикасының Мемлекеттік Гимні.": "Рамзҳои давлатии мамлакати мо — Парчам, Нишон ва Суруди Давлатии Ҷумҳурии Қазоқистон.",
"Гимн деген не?": "Гимн чист?",
"Гимн — мемлекеттік рәміздердің бірі. Бұл — музыкалық шығарма, ол салтанатты мерекелік іс-шараларда орындалады.": "Гимн — яке аз рамзҳои давлатӣ. Ин асари мусиқӣ аст, ки дар чорабиниҳои идонаи тантанавӣ иҷро мешавад.",
"Гимннің авторлары": "Муаллифони Гимн",
"Гимннің әнін Ш. Қалдаяқов жазған, ал өлеңін Ж. Нәжімеденов пен Н. Назарбаев жазған. Гимнді тік тұрып, оң қолды жүрекке қойып тыңдаймыз.": "Оҳанги Гимнро Ш. Калдаяков навиштааст, шеърашро Ж. Нажимеденов ва Н. Назарбаев навиштаанд. Гимнро рост истода, дасти рости худро ба дил гузошта гӯш мекунем.",
"«Дарқан дала» әні": "Суруди «Даркан дала»",
"«Дарқан дала» әнінің өлеңін С. Мәуленов, әнін С. Еркімбеков жазған. Ән оркестр, хор немесе солист түрінде орындалуы мүмкін. Балалар ақыны Абдрахман Асылбектің «Қазақстан — елім менің!» өлеңі де Отанға деген сүйіспеншілікті білдіреді.": "Шеъри сурудаи «Даркан дала»-ро С. Мауленов, оҳангашро С. Еркимбеков навиштаанд. Суруд метавонад аз ҷониби оркестр, хор ё яккахон иҷро шавад. Шеъри «Қазоқистон — Ватани ман!»-и шоири кӯдакон Абдрахман Асылбек низ муҳаббатро ба Ватан ифода мекунад.",
"Кім жазды?": "Кӣ навиштааст?",
"Әр карточканы дұрыс шығармаға қой: Мемлекеттік Гимн немесе «Дарқан дала».": "Ҳар корточкаро ба асари дуруст гузор: Суруди Давлатӣ ё «Даркан дала».",
