"2-сабақ. Нұр-Сұлтан — Қазақстанның астанасы": "Дарс 2. Нур-Султон — пойтахти Қазоқистон",
"Нұр-Сұлтан — Қазақстанның астанасы": "Нур-Султон — пойтахти Қазоқистон",
"Астана туралы әндер мен күйді ажыратып, канон түрінде орындау дегеннің не екенін түсіндіру.": "Фарқ кардани сурудҳо ва куйҳо дар бораи пойтахт ва фаҳмонидани он ки иҷро дар шакли канон чист.",
"Астана — елдің жүрегі": "Пойтахт — дили мамлакат",
"Нұр-Сұлтан — Қазақстанның астанасы. Жыл санап өсіп, көркейіп келеді, оған арналған өлеңдер мен әндер көп.": "Нур-Султон — пойтахти Қазоқистон. Он сол то сол калон шуда, зеботар мегардад; дар бораи он шеърҳо ва сурудҳои зиёд ҳаст.",
"Үлкен ел": "Мамлакати бузург",
"Қазақстан жерінің көлемі жағынан дүниежүзінде тоғызыншы орын алады. Табиғаты сұлу, халқы тату.": "Аз рӯи масоҳати замин Қазоқистон дар ҷаҳон ҷои нӯҳумро ишғол мекунад. Табиати он зебо, халқаш ҳамдил аст.",
"«Арман қала — астана»": "«Шаҳри орзу — пойтахт»",
"Бұл — астанаға арналған ән. Өлеңін де, әнін де М. Омаров жазған. Әннің мазмұны — қаланың көркі мен қуанышы.": "Ин суруд ба пойтахт бахшида шудааст. Ҳам шеъру ҳам оҳангашро М. Омаров навиштааст. Мазмуни суруд — зебоӣ ва шодии шаҳр.",
"«Шабыт» күйі": "Куйи «Шабыт»",
"«Шабыт» — Т. Тоқжановтың күйі. Күйді тыңдап, оның көңіл күйін, қандай сезім сыйлайтынын айтамыз.": "«Шабыт» — куйи Т. Токжанов. Куйро гӯш карда, кайфияти онро ва ҳиссеро, ки мебахшад, мегӯем.",
"Канон дегеніміз не?": "Канон чист?",
"Канон түрінде орындау — әннің негізгі әуенін сақтап, оны топтардың бірінен кейін бірінің қайталап айтуы. Мұны «Дарқан дала» әнінің қайырмасымен үйренеміз.": "Иҷро дар шакли канон — ин нигоҳ доштани оҳанги асосии суруд ва аз паи ҳам такрор кардани он аз ҷониби гурӯҳҳост. Инро бо такрорбанди (припев) сурудаи «Даркан дала» меомӯзем.",
