"Астанаға тарту": "Тӯҳфа ба пойтахт",
"«Астанам» әнін талдап, «Астанаға тарту» ойынының шартын түсіндіру және сөзжұмбақ тапсырмасын атау.": "Таҳлил кардани сурудаи «Астанам», фаҳмонидани шарти бозии «Тӯҳфа ба пойтахт» ва номбар кардани вазифаи сарсанг (кроссворд).",
"«Астанам» әні": "Суруди «Астанам»",
"«Астанам» — елордаға арналған ән. Оның сөзі мен әнін А. Адиханова жазған.": "«Астанам» — суруд барои пойтахт. Калимаҳо ва оҳангашро А. Адиханова навиштааст.",
"Әннің қайырмасы — қайталанып айтылатын басты бөлігі. Қайырма әннің негізгі көңіл күйін жеткізеді.": "Такрорбанди суруд — қисми асосии он аст, ки такрор карда мешавад. Такрорбанд кайфияти асосии сурудро мерасонад.",
"«Астанамызға тарту» ойыны": "Бозии «Тӯҳфа ба пойтахтамон»",
"Сынып үш топқа бөлінеді: «Суретшілер», «Әншілер», «Бишілер». Әр топ астанаға арнайы сыйлық дайындайды.": "Синф ба се гурӯҳ тақсим мешавад: «Рассомон», «Сарояндагон», «Раққосон». Ҳар гурӯҳ ба пойтахт тӯҳфаи махсус тайёр мекунад.",
"Топтардың сыйлығы": "Тӯҳфаи гурӯҳҳо",
"Суретшілер сурет салады, әншілер бір әнді орындайды, бишілер би билейді. Содан кейін әр топ таныстырылым жасап, түсінік береді.": "Рассомон расм мекашанд, сарояндагон як сурудро иҷро мекунанд, раққосон рақс мекунанд. Сипас ҳар гурӯҳ муаррифӣ карда, шарҳ медиҳад.",
"«Астанам — ән қала» сөзжұмбағы": "Сарсанги «Астанам — шаҳри суруд»",
"Сөзжұмбақта қала аттары, «Астанам» сөзі, музыкалық терминдер мен аспап атаулары болады. Олар «ән қала» деген сөздерді құрастырады.": "Дар сарсанг номи шаҳрҳо, калимаи «Астанам», истилоҳҳои мусиқӣ ва номи асбобҳо мешаванд. Онҳо калимаҳои «шаҳри суруд»-ро месозанд.",
"Қай топ қандай сыйлық дайындайды?": "Кадом гурӯҳ чӣ гуна тӯҳфа тайёр мекунад?",
"«Астанамызға тарту» ойынындағы әр әрекетті өз тобына орналастыр.": "Ҳар амалро дар бозии «Тӯҳфа ба пойтахтамон» ба гурӯҳи худаш гузор.",
