"4-сабақ. Туған өлкемді жырлаймын": "Дарс 4. Диёри зодгоҳамро васф мекунам",
"Туған өлкемді жырлаймын": "Диёри зодгоҳамро васф мекунам",
"Туған жер туралы әндерді айту, «ән», «гимн», «канон», «репетиция» ұғымдарын түсіндіру және топта жұмыс істеу.": "Гуфтани сурудҳо дар бораи диёри зодгоҳ, фаҳмонидани мафҳумҳои «суруд», «гимн», «канон», «репетиция» ва дар гурӯҳ кор кардан.",
"Туған өлке": "Диёри зодгоҳ",
"Әр адамның өз туған жері, туған өлкесі бар. Адам қайда жүрсе де, туған жері оған қымбат әрі ыстық.": "Ҳар кас диёри зодгоҳи худро дорад. Одам ба ҳар куҷо равад, диёри зодгоҳаш барояш азиз ва гарм аст.",
"«Менің Отаным» әні": "Сурудаи «Ватани ман»",
"Бұл әнді 1-сыныпта үйрендіңдер. Өлеңін Б. Ысқақов жазған, әнін Ө. Байділдаев шығарған.": "Ин сурудро дар синфи 1 омӯхтед. Шеърашро Б. Искаков навиштааст, оҳангашро О. Байдильдаев эҷод кардааст.",
"Ән деген не?": "Суруд чист?",
"Ән – музыка мен поэзияның ортақ туындысы. Онда әуен мен сөз бірге қосылады.": "Суруд — асари муштараки мусиқӣ ва шеър аст. Дар он оҳанг ва калима якҷоя мешаванд.",
"Репетиция": "Репетиция",
"Репетиция – латын тілінде «қайталау» деген сөз. Дұрыс нәтижеге жету үшін шығарманы бірнеше рет қайталап орындайды.": "Репетиция — дар забони лотинӣ маънояш «такрор» аст. Барои ба натиҷаи дуруст расидан асарро якчанд бор такрор карда иҷро мекунанд.",
"Канон және гимн": "Канон ва гимн",
"Канон – негізгі әуенді бірнеше әнші кезек-кезек қайталап орындауы. Гимн – салтанатты ән, мемлекеттің рәміздерінің бірі; оны тұрып тыңдайды.": "Канон — аз паи ҳам такрор кардани оҳанги асосӣ аз ҷониби якчанд сароянда. Гимн — суруди тантанавӣ, яке аз рамзҳои давлат аст; онро рост истода гӯш мекунанд.",
"Қай топтың тақырыбына жатады?": "Ба мавзӯи кадом гурӯҳ тааллуқ дорад?",
