"Отан-Ана": "Модар-Ватан",
"Түсіндіру: құндылық дегеніміз не, басты құндылықтар қандай, және «Көк тудың желбірегені» әні туралы айту.": "Фаҳмонидан: арзиш чист, арзишҳои асосӣ кадомҳоянд ва дар бораи суруди «Парчами кабуд мепечад» нақл кардан.",
"Құндылық дегеніміз не?": "Арзиш чист?",
"Құндылық – бұл бір нәрсенің мәнділігі, маңыздылығы, қалаулылығы, қымбаттылығы. Адамға тән махаббат, сүйіспеншілік, мейірімділік сезімдері құндылық деп аталады.": "Арзиш – ин аҳамият, муҳимӣ, дилхоҳӣ ва гаронбаҳоии чизе. Ҳисси муҳаббат, меҳру самимият ва меҳрубонӣ, ки хоси инсон аст, арзиш номида мешавад.",
"Басты құндылықтар": "Арзишҳои асосӣ",
"Басты құндылықтар – Отан, отбасы, ана тілі, рәміздер. Әрбір ана үшін баласы қымбат, әрбір адам үшін Отаны қымбат.": "Арзишҳои асосӣ – Ватан, оила, забони модарӣ ва рамзҳо. Барои ҳар модар фарзандаш азиз аст, барои ҳар инсон Ватанаш азиз аст.",
"«Әйел-Ана» ертегісі": "Афсонаи «Зан-Модар»",
"Бұл – жазушы А. Сейдімбектің ертегісі. Күншуақ елі қиын сәтте Әйел-Ананың ақылымен аман қалады.": "Ин афсонаи нависанда А. Сейдимбек аст. Кишвари Куншуақ дар лаҳзаи душвор бо ақли Зан-Модар саломат мемонад.",
"«Көк тудың желбірегені»": "«Парчами кабуд мепечад»",
"Бұл – Отанға, көк туға деген құрметті жырлайтын ән. Өлеңін А. Ахметбекұлы жазған, әнін Е. Зейітхан шығарған.": "Ин суруде аст, ки ба Ватан ва ба парчами кабуд эҳтиромро мехонад. Шеърашро А. Аҳметбекулӣ навиштааст, оҳангашро Е. Зейтхан эҷод кардааст.",
"Әннің құрылысы": "Сохти суруд",
"Әнде екі шумақ пен қайырма бар. Әннің кіріспесін екі топқа бөлініп, екі дауыспен орындауға болады.": "Дар суруд ду банд ва як такрор ҳаст. Оғози сурудро ба ду гурӯҳ тақсим шуда, бо ду овоз иҷро кардан мумкин аст.",
"Қай шығармаға жатады?": "Ба кадом асар тааллуқ дорад?",
