"Дұрыс. Әнде шумақтар мен қайырма бар.": "Дуруст. Дар суруд бандҳо ва такрор ҳаст.",
"Дұрыс. Көк ту – Отанның рәмізі, оған құрмет – Отанға құрмет.": "Дуруст. Парчами кабуд – рамзи Ватан, эҳтиром ба он – эҳтиром ба Ватан.",
"Табыңыз: «Әйел-Ана» ертегісі": "Ёбед: Афсонаи «Зан-Модар»",
"Табыңыз: «Көк тудың желбірегені» әні": "Ёбед: Суруди «Парчами кабуд мепечад»",
"Табыңыз: Басты құндылық": "Ёбед: Арзиши асосӣ",
"Табыңыз: Құндылыққа тән сезім": "Ёбед: Ҳисси хоси арзиш",
"Табыңыз: Құндылықты сипаттайтын сөз": "Ёбед: Калимае, ки арзишро тасвир мекунад",
"6-сабақ. Үлкенге құрмет": "Дарс 6. Эҳтиром ба калонсолон",
"Үлкенге құрмет": "Эҳтиром ба калонсолон",
"Ата-әже туралы әнді тыңдап, оның авторларын, көңіл күйін және құндылықтарын атау; үлкенге құрмет көрсетудің неліктен маңызды екенін түсіндіру.": "Суруди дар бораи бобо ва бибиро гӯш карда, муаллифон, кайфият ва арзишҳои онро номбар кардан; фаҳмонидан, ки чаро эҳтиром ба калонсолон муҳим аст.",
"«Ата-әже» әні": "Суруди «Бобо ва буби»",
"Бұл ән ата-әжеге, әке-анаға деген сүйіспеншілік пен алғыс туралы. Әнді тыңдап, оның мәнін талдаймыз.": "Ин суруд дар бораи меҳр ва ташаккур ба бобо, бибӣ, падар ва модар аст. Сурудро гӯш карда, маънояшро таҳлил мекунем.",
"Ән авторлары": "Муаллифони суруд",
"Өлеңін И. Иса жазған, ал әнін (музыкасын) А. Бексұлтан шығарған. Өлең авторы сөзін, композитор әуенін жазады.": "Шеърашро И. Иса навиштааст, ва оҳангашро (мусиқиашро) А. Бексултан эҷод кардааст. Муаллифи шеър суханро менависад, композитор оҳангро.",
"Шумақ пен қайырма": "Банд ва такрор",
"Әннің бірнеше шумағы және қайырмасы бар. Шумақтардың сөзі өзгереді, ал қайырма әр шумақтан кейін қайталанып айтылады.": "Суруд якчанд банд ва такрор дорад. Суханони бандҳо тағйир меёбад, ва такрор баъд аз ҳар банд такроран хонда мешавад.",
"Құндылықтар": "Арзишҳо",
"Әнде құрмет, алғыс, қамқорлық, мейірім сияқты жақсы қасиеттер айтылады. Бұл қасиеттер отбасын берік етеді.": "Дар суруд сифатҳои нек, ба монанди эҳтиром, ташаккур, ғамхорӣ, меҳрубонӣ гуфта мешавад. Ин сифатҳо оиларо мустаҳкам мекунанд.",
"«Жасырынбақ» ойыны": "Бозии «Пинҳонбозӣ»",
"Бұл суырыпсалма ойын. Екі топқа бөлініп, өсиет өлеңдердегі жасырылған сөздерді табады. Өлеңдер үлкенге құрмет, кішіге ізет туралы.": "Ин бозии бедарангӣ (суръатӣ) аст. Ба ду гурӯҳ тақсим шуда, калимаҳои пинҳоншударо дар шеърҳои панду насиҳат меёбанд. Шеърҳо дар бораи эҳтиром ба калонсолон ва иззати хурдсолон аст.",
"Үлкенге қалай қарау керек?": "Ба калонсол чӣ тавр бояд муносибат кард?",
"Әр әрекетті дұрыс топқа орналастыр.": "Ҳар амалро ба гурӯҳи дуруст ҷой кун.",
"Бұл әрекет қай топқа жатады?": "Ин амал ба кадом гурӯҳ тааллуқ дорад?",
