"«Жасырынбақ» ойынында топтар би билейді.": "Дар бозии «Пинҳонбозӣ» гурӯҳҳо рақс мекунанд.",
"Өлең авторы мен композитор — бір мамандық.": "Муаллифи шеър ва композитор – як касб.",
"Әнді сезіммен орындау керек.": "Сурудро бо ҳис иҷро кардан лозим аст.",
"Дұрыс, өлеңін И. Иса жазған.": "Дуруст, шеърашро И. Иса навиштааст.",
"Әнін А. Бексұлтан шығарған.": "Оҳангашро А. Бексултан эҷод кардааст.",
"Қайырма қайталанып отырады.": "Такрор такрор шуда меистад.",
"Ән ата-әже мен әке-анаға деген құрмет туралы.": "Суруд дар бораи эҳтиром ба бобо, бибӣ, падар ва модар аст.",
"Құрмет — маңызды құндылық.": "Эҳтиром – арзиши муҳим.",
"Үлкен кісіні сыйлап, сөзін бөлмей тыңдаймыз.": "Шахси калонсолро эҳтиром карда, суханашро бурида намегирем, гӯш мекунем.",
"Ойында екі топ жасырылған сөздерді табады.": "Дар бозӣ ду гурӯҳ калимаҳои пинҳоншударо меёбанд.",
"Топтар өлеңдегі жасырылған сөздерді табады.": "Гурӯҳҳо калимаҳои дар шеър пинҳоншударо меёбанд.",
"Өлең авторы сөзін, композитор әуенін шығарады.": "Муаллифи шеър суханро, композитор оҳангро эҷод мекунад.",
"Көңіл күйді дауыспен жеткізген жөн.": "Кайфиятро бо овоз расонидан лозим аст.",
"Дұрыс. Дұрыс, өлеңін И. Иса жазған.": "Дуруст. Дуруст, шеърашро И. Иса навиштааст.",
"Бұрыс. Әнін А. Бексұлтан шығарған.": "Нодуруст. Оҳангашро А. Бексултан эҷод кардааст.",
"Дұрыс. Қайырма қайталанып отырады.": "Дуруст. Такрор такрор шуда меистад.",
"Бұрыс. Ән ата-әже мен әке-анаға деген құрмет туралы.": "Нодуруст. Суруд дар бораи эҳтиром ба бобо, бибӣ, падар ва модар аст.",
"Дұрыс. Құрмет — маңызды құндылық.": "Дуруст. Эҳтиром – арзиши муҳим.",
"Бұрыс. Үлкен кісіні сыйлап, сөзін бөлмей тыңдаймыз.": "Нодуруст. Шахси калонсолро эҳтиром карда, суханашро бурида намегирем, гӯш мекунем.",
"Дұрыс. Ойында екі топ жасырылған сөздерді табады.": "Дуруст. Дар бозӣ ду гурӯҳ калимаҳои пинҳоншударо меёбанд.",
"Бұрыс. Топтар өлеңдегі жасырылған сөздерді табады.": "Нодуруст. Гурӯҳҳо калимаҳои дар шеър пинҳоншударо меёбанд.",
"Бұрыс. Өлең авторы сөзін, композитор әуенін шығарады.": "Нодуруст. Муаллифи шеър суханро, композитор оҳангро эҷод мекунад.",
"Дұрыс. Көңіл күйді дауыспен жеткізген жөн.": "Дуруст. Кайфиятро бо овоз расонидан лозим аст.",
"Табыңыз: Үлкенге құрмет көрсету": "Ёбед: Нишон додани эҳтиром ба калонсол",
"Табыңыз: Үлкенге құрметсіздік": "Ёбед: Беэҳтиромӣ ба калонсол",
"Табыңыз: Талдау": "Ёбед: Таҳлил",
"Табыңыз: Ән айту": "Ёбед: Суруд хондан",
"Табыңыз: Ойын және шығармашылық": "Ёбед: Бозӣ ва эҷодкорӣ",
"7-сабақ. Достығымыз жарасқан": "Дарс 7. Дӯстии мо ҳамоҳанг",
"Достығымыз жарасқан": "Дӯстии мо ҳамоҳанг",
"«Жан досым» және «Достар әні» әндерінің авторларын атау, достықтың құндылықтарын түсіндіру және әннің орындалу ерекшеліктерін сипаттау.": "Номбар кардани муаллифони суруди «Дӯсти ҷонӣ» ва «Суруди дӯстон», фаҳмондани арзишҳои дӯстӣ ва тавсиф кардани хусусиятҳои иҷрои суруд.",
"«Жан досым» әні": "Суруди «Дӯсти ҷонӣ»",
"Бұл әннің өлеңін Т. Молдағалиев жазған, әнін (музыкасын) композитор С. Бәйтереков шығарған. Ән жақын досқа арналған.": "Шеъри ин сурудро Т. Молдагалиев навиштааст, оҳангашро (мусиқиашро) композитор С. Байтереков эҷод кардааст. Суруд ба дӯсти наздик бахшида шудааст.",
"«Достар әні»": "«Суруди дӯстон»",
"Бұл әннің өлеңін А. Рахметов жазған, әнін Н. Мирманов шығарған. Ән достық, бірге болу туралы.": "Шеъри ин сурудро А. Раҳметов навиштааст, оҳангашро Н. Мирманов эҷод кардааст. Суруд дар бораи дӯстӣ ва бо ҳам будан аст.",
"Неліктен «Жан досым»?": "Чаро «Дӯсти ҷонӣ»?",
"«Жан дос» дегеніміз – ең жақын, сенімді дос. Ән осындай досқа арналғандықтан, солай аталған.": "«Дӯсти ҷонӣ» – наздиктарин, боэътимод дӯст. Суруд ба чунин дӯст бахшида шудааст, барои ҳамин чунин ном гирифтааст.",
"Достықтың құндылықтары": "Арзишҳои дӯстӣ",
"Нағыз дос адал, қамқор, сенімді болады. Бір-біріне көмектесу, сыйлау және сырласу – достықты нығайтады.": "Дӯсти ҳақиқӣ поквиҷдон, ғамхор ва боэътимод мешавад. Ба якдигар кумак кардан, эҳтиром намудан ва розгӯӣ кардан – дӯстиро мустаҳкам мекунад.",
"Әннің орындалу ерекшелігі": "Хусусияти иҷрои суруд",
"Ән баяу немесе жылдам айтылуы мүмкін – бұл оның екпіні. Көңіл күйі лирикалы, ойнақы немесе жігерлі болады. Кейбір ән биге, кейбірі маршқа жақын ырғақпен орындалады.": "Суруд метавонад оҳиста ё тез хонда шавад – ин суръати он аст. Кайфияташ лирикӣ, бозингар ё пурҷӯшу хурӯш мешавад. Баъзе суруд бо ритми рақс, баъзеаш бо ритми марш наздик иҷро мешавад.",
"Дос қандай болады?": "Дӯст чӣ гуна мешавад?",
"Достың жақсы қасиеттерін басқа қасиеттерден ажыратыңдар.": "Сифатҳои некӣ дӯстро аз сифатҳои дигар фарқ кунед.",
"Бұл қасиет нағыз досқа тән бе?": "Ин сифат хоси дӯсти ҳақиқӣ аст ё не?",
