"Табыңыз: Досқа жараспайды": "Ёбед: Ба дӯст мувофиқ нест",
"Табыңыз: Баяу, жұмсақ сипат": "Ёбед: Хусусияти оҳиста, нарм",
"Табыңыз: Жылдам, жігерлі сипат": "Ёбед: Хусусияти тез, пурҷӯшу хурӯш",
"8-сабақ. Құндылықтар шеңбері": "Дарс 8. Давраи арзишҳо",
"Құндылықтар шеңбері": "Давраи арзишҳо",
"Құндылықтар деген не екенін түсіндіру, Н. Мирмановтың «Достар» және С. Бәйтерековтің «Көк тудың желбірегені» әндерін атау, f және p таңбаларын ажырату.": "Фаҳмондани он ки арзишҳо чист, номбар кардани сурудҳои «Дӯстон»-и Н. Мирманов ва «Парчами кабуд мепечад»-и С. Байтереков, фарқ кардани аломатҳои f ва p.",
"Құндылықтар деген не?": "Арзишҳо чист?",
"Құндылықтар – адам үшін ең қымбат нәрселер: Отан-Ана, Жер, ұлт, ана тілі, отбасы, достық. Мейірімділік, адалдық, қайырымдылық та – жақсы қасиеттер.": "Арзишҳо – азизтарин чизҳо барои инсон: Модар-Ватан, Замин, миллат, забони модарӣ, оила, дӯстӣ. Меҳрубонӣ, поквиҷдонӣ, нексириштӣ низ – сифатҳои нек.",
"Шаңырақ пен уықтар": "Шанирақ ва уиқҳо",
"Сабақта құндылықтар шаңырақ пен уықтар арқылы көрсетілген. Шаңырақ – киіз үйдің төбесі, ал уықтар – оны ұстап тұратын таяқтар. Әр уықта бір құндылық тұр.": "Дар дарс арзишҳо тавассути шанирақ ва уиқҳо нишон дода шудаанд. Шанирақ – сақфи хонаи намадии қазоқӣ (киизуй), уиқҳо бошанд – чӯбҳое, ки онро нигоҳ медоранд. Дар ҳар уиқ як арзиш истодааст.",
"Ту, Гимн және Елтаңба – мемлекеттік рәміздер. Олар да біздің ортақ құндылықтарымыз қатарына жатады.": "Парчам, Суруди миллӣ ва Нишон – рамзҳои давлатӣ. Онҳо низ ба қатори арзишҳои умумии мо тааллуқ доранд.",
"Достық туралы ән": "Суруд дар бораи дӯстӣ",
"Н. Мирмановтың «Достар» әні достықты жырлайды. Достық – адамның ең сенімді серігі болу дегенді білдіреді.": "Суруди «Дӯстон»-и Н. Мирманов дӯстиро мекушояд. Дӯстӣ маънои ҳамсафари боэътимодтарини инсон будан аст.",
"Динамикалық таңбалар": "Аломатҳои динамикӣ",
"f (форте) – әнді қатты орындау, p (пиано) – жай орындау. Бұл таңбалар музыканың қаншалықты қатты немесе жай шығатынын көрсетеді.": "f (форте) – сурудро баланд иҷро кардан, p (пиано) – оҳиста иҷро кардан. Ин аломатҳо нишон медиҳанд, ки мусиқӣ то чӣ андоза баланд ё оҳиста садо медиҳад.",
"Құндылықтар мен қасиеттерді ретте": "Арзишҳо ва сифатҳоро ба тартиб даровар",
"Әр сөзді өз тобына апар: мемлекеттік рәміздер, жақсы қасиеттер немесе жаман қасиеттер.": "Ҳар калимаро ба гурӯҳи худаш бибар: рамзҳои давлатӣ, сифатҳои нек ё сифатҳои бад.",
